// Find and clean up orphaned photo references in hikes
export async function cleanupOrphanedPhotoReferences() {
  try {
    console.log("Starting cleanup of orphaned photo references...");

    // Get all hikes
    const hikesQuery = query(collection(db, "hikes"));
    const hikesSnapshot = await getDocs(hikesQuery);

    // Get all valid photo IDs from the photos collection
    const photosQuery = query(collection(db, "photos"));
    const photosSnapshot = await getDocs(photosQuery);
    const validPhotoIds = new Set();

    photosSnapshot.forEach((doc) => {
      validPhotoIds.add(doc.id);
    });

    console.log(`Found ${validPhotoIds.size} valid photos in database`);

    let totalOrphaned = 0;
    let hikesUpdated = 0;

    // Check each hike for orphaned photo references
    for (const hikeDoc of hikesSnapshot.docs) {
      const hikeData = hikeDoc.data();
      const currentPhotos = hikeData.photos || [];

      if (currentPhotos.length === 0) continue;

      // Filter out any photos that don't exist in the photos collection
      const cleanedPhotos = currentPhotos.filter((photo) => {
        if (!photo || !photo.id) {
          console.warn(`Invalid photo object in hike ${hikeDoc.id}:`, photo);
          return false;
        }
        const isValid = validPhotoIds.has(photo.id);
        if (!isValid) {
          console.warn(
            `Found orphaned photo reference: ${photo.id} in hike ${hikeDoc.id}`,
          );
          totalOrphaned++;
        }
        return isValid;
      });

      // Update hike if we removed any orphaned references
      if (cleanedPhotos.length < currentPhotos.length) {
        await updateDoc(doc(db, "hikes", hikeDoc.id), {
          photos: cleanedPhotos,
        });
        console.log(
          `✓ Updated hike ${hikeDoc.id}: removed ${
            currentPhotos.length - cleanedPhotos.length
          } orphaned references`,
        );
        hikesUpdated++;
      }
    }

    console.log(
      `Cleanup complete: ${totalOrphaned} orphaned references removed from ${hikesUpdated} hikes`,
    );
    return {
      success: true,
      totalOrphaned,
      hikesUpdated,
    };
  } catch (error) {
    console.error("Error cleaning up orphaned photo references:", error);
    return {
      success: false,
      error: error.message,
    };
  }
}

// Batch cleanup orphaned storage files
export async function cleanupOrphanedStorageFiles() {
  try {
    console.log("Starting cleanup of orphaned storage files...");

    // Get all photos from Firestore
    const allPhotosQuery = query(
      collection(db, "photos"),
      orderBy("uploadedAt", "desc"),
    );
    const querySnapshot = await getDocs(allPhotosQuery);

    const validFilePaths = new Set();

    // Build a set of all valid file paths
    querySnapshot.forEach((doc) => {
      const photoData = doc.data();
      if (photoData.fileName) {
        validFilePaths.add(`photos/${photoData.hikeId}/${photoData.fileName}`);
      }
      if (photoData.thumbnailFileName) {
        validFilePaths.add(
          `photos/${photoData.hikeId}/${photoData.thumbnailFileName}`,
        );
      }
    });

    console.log(`Found ${validFilePaths.size} valid file paths in Firestore`);

    // Note: Firebase Storage doesn't have a direct way to list all files
    // This is a limitation of the Firebase Storage API
    // In a real production environment, you would need to maintain a separate
    // index of all uploaded files or use a different storage solution
    // that supports file listing

    console.log(
      "Storage cleanup completed. Note: Manual verification recommended.",
    );
    console.log("Valid file paths:", Array.from(validFilePaths));

    return {
      success: true,
      validFilePaths: Array.from(validFilePaths),
      message:
        "Cleanup completed. Manual verification recommended due to Storage API limitations.",
    };
  } catch (error) {
    console.error("Error during storage cleanup:", error);
    return {
      success: false,
      error: error.message,
    };
  }
}
